-- Jade Steam: run once in Supabase SQL Editor. Public site uses anon key only.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'customer' check(role in ('customer','affiliate','admin')), full_name text, created_at timestamptz default now());
create table if not exists public.store_settings (id boolean primary key default true check(id), affiliate_enabled boolean not null default false, promos_enabled boolean not null default false, referral_window_days int not null default 30 check(referral_window_days between 1 and 365));
insert into public.store_settings(id) values(true) on conflict do nothing;
create table if not exists public.products (id bigint generated by default as identity primary key, name text not null, category text not null, description text default '', price numeric(12,2) not null check(price>=0), pass_on_price numeric(12,2) not null default 0 check(pass_on_price>=0), stock int not null default 0 check(stock>=0), active boolean not null default true, image_url text, size_label text, variants jsonb not null default '["Original"]'::jsonb, storage_instructions text, cooking_instructions text, created_at timestamptz default now());
create table if not exists public.promos (id uuid primary key default gen_random_uuid(), name text not null, code text not null unique, kind text not null check(kind in ('fixed','percent','shipping')), value numeric(12,2) not null check(value>=0), minimum_spend numeric(12,2) not null default 0, max_discount numeric(12,2), starts_at timestamptz, ends_at timestamptz, max_uses int, per_customer_limit int, eligible_product_ids bigint[], active boolean not null default false, used_count int not null default 0);
create table if not exists public.affiliates (id uuid primary key default gen_random_uuid(), user_id uuid unique references auth.users(id), full_name text not null, email text not null, phone text, referral_code text unique not null, status text not null default 'pending' check(status in ('pending','active','inactive','rejected')), payout_details text, commission_type text not null default 'percent' check(commission_type in ('percent','fixed')), commission_value numeric(12,2) not null default 0, created_at timestamptz default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), reference text not null unique default ('DST-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), customer_name text not null, customer_email text not null, customer_phone text not null, delivery_address jsonb not null, delivery_schedule text, delivery_instructions text, subtotal numeric(12,2) not null, discount numeric(12,2) not null default 0, shipping_fee numeric(12,2) not null, total numeric(12,2) not null, promo_id uuid references public.promos(id), affiliate_id uuid references public.affiliates(id), payment_status text not null default 'pending' check(payment_status in ('pending','submitted','verified','rejected')), order_status text not null default 'submitted' check(order_status in ('submitted','preparing','out_for_delivery','delivered','cancelled','refunded')), courier_tracking_url text, created_at timestamptz default now());
create table if not exists public.order_items (id bigint generated always as identity primary key, order_id uuid not null references public.orders(id) on delete cascade, product_id bigint references public.products(id), product_name text not null, variant text, quantity int not null check(quantity>0), unit_price numeric(12,2) not null, pass_on_price numeric(12,2) not null default 0);
create table if not exists public.payment_submissions (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), method text not null check(method in ('gcash','bank')), reference_number text not null, amount_sent numeric(12,2) not null check(amount_sent>0), paid_at timestamptz not null, proof_path text, review_status text not null default 'pending' check(review_status in ('pending','verified','rejected')), reviewed_by uuid references auth.users(id), reviewed_at timestamptz, created_at timestamptz default now());
create table if not exists public.commissions (id uuid primary key default gen_random_uuid(), affiliate_id uuid not null references public.affiliates(id), order_id uuid not null unique references public.orders(id), amount numeric(12,2) not null, status text not null default 'pending' check(status in ('pending','approved','paid','void')), created_at timestamptz default now());
create table if not exists public.affiliate_clicks (id bigint generated always as identity primary key, affiliate_id uuid references public.affiliates(id), clicked_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to authenticated;
alter table public.profiles enable row level security;
alter table public.store_settings enable row level security;
alter table public.products enable row level security;
alter table public.promos enable row level security;
alter table public.affiliates enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.payment_submissions enable row level security;
alter table public.commissions enable row level security;
alter table public.affiliate_clicks enable row level security;
create policy "own profile or admin" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "settings public read" on public.store_settings for select to anon,authenticated using(true);
create policy "settings admin write" on public.store_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "active products public read" on public.products for select to anon,authenticated using(active or public.is_admin());
create policy "products admin manage" on public.products for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "promos admin only" on public.promos for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "affiliates own or admin read" on public.affiliates for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy "affiliates admin manage" on public.affiliates for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "orders admin only" on public.orders for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "items admin only" on public.order_items for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "payments admin only" on public.payment_submissions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "commissions admin only" on public.commissions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "clicks admin only" on public.affiliate_clicks for all to authenticated using(public.is_admin()) with check(public.is_admin());
-- Guest checkout: compute totals from database, never trust browser prices. Shipping fee provided by admin-configured zone later.
-- Until shipping distance can be verified server-side, do not accept real guest orders.
-- Payment review remains admin-only and must be based on independently checked incoming funds.
create or replace function public.review_payment(p_submission uuid,p_approve boolean) returns void language plpgsql security definer set search_path=public as $$
declare v_order uuid;
begin
 if not public.is_admin() then raise exception 'Not authorized'; end if;
 select order_id into v_order from public.payment_submissions where id=p_submission and review_status='pending' for update;
 if v_order is null then raise exception 'Submission not found or already reviewed'; end if;
 update public.payment_submissions set review_status=case when p_approve then 'verified' else 'rejected' end, reviewed_by=auth.uid(), reviewed_at=now() where id=p_submission;
 update public.orders set payment_status=case when p_approve then 'verified' else 'rejected' end where id=v_order;
end $$;
revoke all on function public.review_payment(uuid,boolean) from public,anon; grant execute on function public.review_payment(uuid,boolean) to authenticated;
-- Seed sample catalog once; replace names/prices with actual business data.
insert into public.products(name,category,description,price,pass_on_price,stock,size_label,variants,storage_instructions,cooking_instructions)
select v.name,v.category,v.description,v.price,0,v.stock,v.size_label,v.variants::jsonb,'Keep refrigerated.','Steam or heat thoroughly.' from (values
('Pork Siomai','Steamed','Classic pork dumplings',185,12,'6 pieces','["Classic","Chili Garlic"]'),
('Shrimp Har Gow','Steamed','Shrimp dumplings',225,9,'6 pieces','["Original"]'),
('Char Siu Bao','Buns','Steamed barbecue buns',155,20,'3 buns','["Classic","Extra Filling"]'),
('Egg Tarts','Sweets','Custard pastry tarts',220,6,'4 pieces','["Classic"]')) as v(name,category,description,price,stock,size_label,variants)
where not exists(select 1 from public.products);
